"""Offline client handoff guide; original Logo Parcel styling."""
import base64,html,json,re
from collections import OrderedDict
from pathlib import Path
from urllib.parse import quote

def guide(brand, files, warnings, notes, previews=None, website=''):
    esc=html.escape
    previews=previews or {}
    groups=OrderedDict()
    for item in files:
        groups.setdefault((item.get('role',Path(item['path']).parts[0]),item['variant'],item['mode']),[]).append(item)
    cards=[]
    for index,((role,variant,mode),items) in enumerate(groups.items(),1):
        candidates=[Path(previews[i['id']]) for i in items if previews.get(i['id']) and Path(previews[i['id']]).is_file()]
        visual='<div class="no-preview">'+esc(role)+'</div>'
        if candidates:
            thumb=min(candidates,key=lambda p:p.stat().st_size)
            if thumb.stat().st_size<=3_000_000:
                visual='<img alt="'+esc(role+' — '+variant.replace('-',' '),quote=True)+'" loading="lazy" src="data:image/png;base64,'+base64.b64encode(thumb.read_bytes()).decode('ascii')+'">'
        else:
            raster=next((i for i in items if i['format'] in ('png','svg','jpg')),None)
            if raster: visual='<img alt="'+esc(role,quote=True)+'" loading="lazy" src="'+quote(raster['path'],safe='/')+'">'
        links=[]
        for item in items:
            label=item['format'].upper()+(' · '+str(item['size'])+'px' if item.get('size') else '')
            links.append('<a class="file" download href="'+quote(item['path'],safe='/')+'" title="'+esc(Path(item['path']).name,quote=True)+'">'+esc(label)+'<span aria-hidden="true">↗</span></a>')
        cards.append('<article class="card" data-mode="'+esc(mode,quote=True)+'" data-search="'+esc((role+' '+variant).lower(),quote=True)+'"><div class="card-top"><span class="number">'+f'{index:02d}'+'</span><span class="mono">'+('DIGITAL / RGB' if mode=='rgb' else 'PRINT / CMYK')+'</span></div><div class="preview '+('dark' if variant=='white' else '')+'">'+visual+'</div><div class="card-content"><h3>'+esc(role)+'</h3><p class="variant">'+esc(variant.replace('-',' ').capitalize())+'</p><div class="files">'+''.join(links)+'</div></div></article>')
    credits='<a href="'+esc(website,quote=True)+'" target="_blank" rel="noopener noreferrer">Stellio Creative Labs ↗</a>' if website else 'Stellio Creative Labs'
    notes_html=''.join('<li>'+esc(n)+'</li>' for n in notes)
    warning_html='<aside class="warning"><h2>Before you use these files</h2><ul>'+''.join('<li>'+esc(w)+'</li>' for w in warnings)+'</ul></aside>' if warnings else ''
    values={'TITLE':esc(brand),'COUNT':str(len(files)),'LAYOUTS':str(len({i.get('role',str(i['layout'])) for i in files})),'CARDS':''.join(cards),'NOTES':notes_html,'WARNINGS':warning_html,'CREDITS':credits}
    return re.sub(r'__(TITLE|COUNT|LAYOUTS|CARDS|NOTES|WARNINGS|CREDITS)__',lambda m:values[m[1]],TEMPLATE)

